// The society seal (D-137) for printed documents, 192 px, from assets/images/seal.png. expo-print renders
// plain HTML and cannot load bundled assets, so the image travels inside the page as a data URI.
// Regenerate: ffmpeg -i assets/images/seal.png -vf scale=192:192:flags=lanczos seal192.png, then base64.
export const SEAL_DATA_URI = 'data:image/png;base64,';
